Subroutine Suspendable Cook(price As Integer, portions As Integer) As Integer
  Return price * portions;
EndSubroutine

Algorithm Tray
  Define juices As Integer;
  Define sandwiches As Integer;
  Define fruits As Integer;
  Read juices;
  Read sandwiches;
  Read fruits;
  Tasks
    Define ofJuices As Task<Integer> <- Spawn Cook(3, juices);
    Define ofSandwiches As Task<Integer> <- Spawn Cook(5, sandwiches);
    Define ofFruits As Task<Integer> <- Spawn Cook(2, fruits);
    Write "Tray: ", Await ofJuices + Await ofSandwiches + Await ofFruits, " pesos";
  EndTasks
EndAlgorithm
